def delete_item(conn, item_id):
    """Delete one ITEM row. Returns a structured result instead of
    raising for either of ITEM's two expected non-success outcomes:

        {"deleted": True}
        {"deleted": False, "reason": "not_found"}
        {"deleted": False, "reason": "referenced"}
    """
    cursor = conn.cursor()
    try:
        cursor.execute("DELETE FROM ITEM WHERE ITEM_ID = %s", (item_id,))
        if cursor.rowcount == 0:
            conn.rollback()
            return {"deleted": False, "reason": "not_found"}
        conn.commit()
        return {"deleted": True}
    except mysql.connector.errors.IntegrityError as exc:
        conn.rollback()
        # errno 1451: "Cannot delete or update a parent row: a
        #   foreign key constraint fails" -- the exact error a real
        #   MySQL server raises for this table shape.
        if exc.errno == 1451:
            return {"deleted": False, "reason": "referenced"}
        raise
    finally:
        cursor.close()

