@app.errorhandler(Exception)
def handle_unexpected_error(exc):
    # The only place a database or programming error is allowed to
    # reach a client at all -- and only ever as this one generic
    # message. The real exception goes to the server log instead.
    logger.exception("Unhandled error in %s %s", request.method, request.path)
    return _error(500, "internal_error", "Something went wrong. Check the server log.")

